//! Shared role-based access control, two-step admin handover, and pause flag.
//!
//! Every contract that uses this module stores the same keys ([`AccessKey`])
//! and exposes the same entrypoints, generated by
//! [`impl_access_control!`](crate::impl_access_control) from
//! [`AccessControlInterface`](crate::AccessControlInterface). One
//! implementation, one test suite.
//!
//! ## Model
//!
//! * **Admin** — exactly one address, stored in instance storage. Meant to be
//!   the `RefractTimelock` contract so that governance controls the contract.
//!   It changes hands only through [`propose_admin`] followed by
//!   [`accept_admin`] from the proposed address; a typo in step one is
//!   recoverable by proposing again. The admin passes every role check.
//! * **Other roles** ([`Role::Operator`], [`Role::Approver`],
//!   [`Role::Pauser`], [`Role::Upgrader`]) — any number of holders, granted
//!   and revoked by the admin, stored in persistent storage under
//!   [`AccessKey::Role`].
//! * **Pause flag** — set by a pauser. While paused, role changes are refused
//!   except for the pauser role itself, and admin handover still works, so an
//!   incident can be handled without first unpausing.
//!
//! ## Storage and TTL
//!
//! | Key | Storage | TTL |
//! |-----|---------|-----|
//! | [`AccessKey::Admin`], [`AccessKey::PendingAdmin`], [`AccessKey::Paused`] | instance | lives with the contract instance |
//! | [`AccessKey::Role`] | persistent | extended to [`ROLE_TTL_EXTEND_TO`] ledgers (about 120 days) on grant and on every check that finds it, once it drops below [`ROLE_TTL_THRESHOLD`] (about 30 days) |
//!
//! The contract instance (which holds the admin, pending admin and pause
//! flag) is extended to the same TTL by [`init`] and every role check, via
//! [`extend_instance_ttl`].
//!
//! A role entry that is never touched for longer than its TTL is archived by
//! the network and has to be restored before the holder can use it again.
//!
//! ## Auth with the timelock as admin
//!
//! Every check calls `caller.require_auth()`. When the timelock forwards a
//! call with `caller = <timelock address>`, the host satisfies that auth
//! automatically because the timelock is the direct invoker, so no signature
//! is needed.

use soroban_sdk::{contracttype, Address, BytesN, Env, Symbol};

use crate::errors::RefractError;
use crate::types::Role;

/// Ledgers per day at the 5-second target close time.
pub const LEDGERS_PER_DAY: u32 = 17_280;

/// A role entry whose TTL drops below this is extended (about 30 days).
pub const ROLE_TTL_THRESHOLD: u32 = 30 * LEDGERS_PER_DAY;

/// The TTL a role entry is extended to (about 120 days).
pub const ROLE_TTL_EXTEND_TO: u32 = 120 * LEDGERS_PER_DAY;

/// Keep the contract instance (and with it the admin and pause flag) alive.
/// Called by [`init`] and every role check; contracts may call it from their
/// own hot paths too.
pub fn extend_instance_ttl(env: &Env) {
    env.storage()
        .instance()
        .extend_ttl(ROLE_TTL_THRESHOLD, ROLE_TTL_EXTEND_TO);
}

/// Storage keys owned by this module. Contracts must not reuse them.
#[contracttype]
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum AccessKey {
    /// Current admin (instance).
    Admin,
    /// Admin proposed by `propose_admin`, waiting for `accept_admin`
    /// (instance).
    PendingAdmin,
    /// Presence means `Address` holds `Role` (persistent).
    Role(Role, Address),
    /// `true` while paused (instance).
    Paused,
}

/// Set the first admin. Call once from the contract's `initialize`.
pub fn init(env: &Env, admin: &Address) -> Result<(), RefractError> {
    if env.storage().instance().has(&AccessKey::Admin) {
        return Err(RefractError::AlreadyInitialized);
    }
    if *admin == env.current_contract_address() {
        return Err(RefractError::InvalidArgument);
    }
    env.storage().instance().set(&AccessKey::Admin, admin);
    extend_instance_ttl(env);
    Ok(())
}

/// The current admin.
pub fn admin(env: &Env) -> Result<Address, RefractError> {
    env.storage()
        .instance()
        .get(&AccessKey::Admin)
        .ok_or(RefractError::NotInitialized)
}

/// The admin proposed by [`propose_admin`], if a handover is in progress.
pub fn pending_admin(env: &Env) -> Option<Address> {
    env.storage().instance().get(&AccessKey::PendingAdmin)
}

/// Whether `account` holds `role`. The admin holds [`Role::Admin`] and no
/// explicit grants; use [`require_role`] for checks, which also lets the
/// admin through.
pub fn has_role(env: &Env, role: Role, account: &Address) -> bool {
    extend_instance_ttl(env);
    if role == Role::Admin {
        return admin(env).map(|a| a == *account).unwrap_or(false);
    }
    let key = AccessKey::Role(role, account.clone());
    let storage = env.storage().persistent();
    if storage.has(&key) {
        storage.extend_ttl(&key, ROLE_TTL_THRESHOLD, ROLE_TTL_EXTEND_TO);
        true
    } else {
        false
    }
}

/// Require `caller`'s auth and that `caller` is the admin.
pub fn require_admin(env: &Env, caller: &Address) -> Result<(), RefractError> {
    caller.require_auth();
    extend_instance_ttl(env);
    if admin(env)? != *caller {
        return Err(RefractError::Unauthorized);
    }
    Ok(())
}

/// Require `caller`'s auth and that `caller` holds `role` or is the admin.
pub fn require_role(env: &Env, role: Role, caller: &Address) -> Result<(), RefractError> {
    caller.require_auth();
    extend_instance_ttl(env);
    if admin(env)? == *caller || has_role(env, role, caller) {
        return Ok(());
    }
    Err(RefractError::Unauthorized)
}

/// Grant `role` to `account`. Admin only. The admin role cannot be granted
/// (use [`propose_admin`]), no role can be granted to the contract itself,
/// and only the pauser role can be granted while paused.
pub fn grant_role(
    env: &Env,
    caller: &Address,
    role: Role,
    account: &Address,
) -> Result<(), RefractError> {
    require_admin(env, caller)?;
    check_role_change(env, role, account)?;
    let key = AccessKey::Role(role, account.clone());
    if env.storage().persistent().has(&key) {
        return Err(RefractError::AlreadyExists);
    }
    env.storage().persistent().set(&key, &true);
    env.storage()
        .persistent()
        .extend_ttl(&key, ROLE_TTL_THRESHOLD, ROLE_TTL_EXTEND_TO);
    env.events().publish(
        (Symbol::new(env, "role_granted"), role, account.clone()),
        caller.clone(),
    );
    Ok(())
}

/// Revoke `role` from `account`. Admin only, same restrictions as
/// [`grant_role`].
pub fn revoke_role(
    env: &Env,
    caller: &Address,
    role: Role,
    account: &Address,
) -> Result<(), RefractError> {
    require_admin(env, caller)?;
    check_role_change(env, role, account)?;
    let key = AccessKey::Role(role, account.clone());
    if !env.storage().persistent().has(&key) {
        return Err(RefractError::NotFound);
    }
    env.storage().persistent().remove(&key);
    env.events().publish(
        (Symbol::new(env, "role_revoked"), role, account.clone()),
        caller.clone(),
    );
    Ok(())
}

fn check_role_change(env: &Env, role: Role, account: &Address) -> Result<(), RefractError> {
    if role == Role::Admin || *account == env.current_contract_address() {
        return Err(RefractError::InvalidArgument);
    }
    if is_paused(env) && role != Role::Pauser {
        return Err(RefractError::Paused);
    }
    Ok(())
}

/// Step one of the admin handover: record `new_admin` as pending. Admin
/// only. Proposing again replaces the pending address. The contract itself
/// and the current admin are rejected.
pub fn propose_admin(env: &Env, caller: &Address, new_admin: &Address) -> Result<(), RefractError> {
    require_admin(env, caller)?;
    if *new_admin == env.current_contract_address() || new_admin == caller {
        return Err(RefractError::InvalidArgument);
    }
    env.storage()
        .instance()
        .set(&AccessKey::PendingAdmin, new_admin);
    env.events().publish(
        (Symbol::new(env, "admin_proposed"), caller.clone()),
        new_admin.clone(),
    );
    Ok(())
}

/// Step two of the admin handover: the pending admin accepts. Anyone else is
/// rejected with [`RefractError::Unauthorized`].
pub fn accept_admin(env: &Env, caller: &Address) -> Result<(), RefractError> {
    caller.require_auth();
    let pending = pending_admin(env).ok_or(RefractError::NoPendingAdmin)?;
    if pending != *caller {
        return Err(RefractError::Unauthorized);
    }
    let previous = admin(env)?;
    env.storage().instance().set(&AccessKey::Admin, caller);
    env.storage().instance().remove(&AccessKey::PendingAdmin);
    env.events().publish(
        (Symbol::new(env, "admin_accepted"), previous),
        caller.clone(),
    );
    Ok(())
}

/// Whether the contract is paused.
pub fn is_paused(env: &Env) -> bool {
    env.storage()
        .instance()
        .get(&AccessKey::Paused)
        .unwrap_or(false)
}

/// Fail with [`RefractError::Paused`] while paused.
pub fn require_not_paused(env: &Env) -> Result<(), RefractError> {
    if is_paused(env) {
        return Err(RefractError::Paused);
    }
    Ok(())
}

/// Pause the contract. Pauser role (or admin).
pub fn pause(env: &Env, caller: &Address) -> Result<(), RefractError> {
    require_role(env, Role::Pauser, caller)?;
    env.storage().instance().set(&AccessKey::Paused, &true);
    env.events()
        .publish((Symbol::new(env, "paused"),), caller.clone());
    Ok(())
}

/// Unpause the contract. Pauser role (or admin).
pub fn unpause(env: &Env, caller: &Address) -> Result<(), RefractError> {
    require_role(env, Role::Pauser, caller)?;
    env.storage().instance().set(&AccessKey::Paused, &false);
    env.events()
        .publish((Symbol::new(env, "unpaused"),), caller.clone());
    Ok(())
}

/// Replace the contract's wasm. Upgrader role (or admin).
pub fn upgrade(
    env: &Env,
    caller: &Address,
    new_wasm_hash: &BytesN<32>,
) -> Result<(), RefractError> {
    require_role(env, Role::Upgrader, caller)?;
    env.deployer()
        .update_current_contract_wasm(new_wasm_hash.clone());
    env.events()
        .publish((Symbol::new(env, "upgraded"),), new_wasm_hash.clone());
    Ok(())
}
